def normalize(value):
    abbreviations = {"ave": "avenue", "rd": "road", "st": "street"}
    tokens = re.sub(r"[^a-z0-9 ]", " ", value.lower()).split()
    return " ".join(abbreviations.get(token, token) for token in tokens)


def consolidate_exact_duplicates(apps):
    EndUser = apps.get_model("registrations", "EndUser")
    groups = {}
    for item in EndUser.objects.filter(is_active=True).order_by("id"):
        key = (normalize(item.official_name), normalize(item.normalized_address))
        groups.setdefault(key, []).append(item)
    for records in groups.values():
        if len(records) < 2:
            continue
        canonical = sorted(
            records,
            key=lambda item: (
                item.status != "verified",
                -(item.registrations.count() + item.opportunities.count()),
                item.id,
            ),
        )[0]
        for duplicate in records:
            if duplicate.pk == canonical.pk:
                continue
            duplicate.registrations.update(end_user=canonical)
            duplicate.opportunities.update(end_user=canonical)
            duplicate.sub_organizations.update(parent=canonical)
            duplicate.is_active = False
            duplicate.save(update_fields=["is_active"])


def seed_common_end_users(apps, schema_editor):
    EndUser = apps.get_model("registrations", "EndUser")
    EndUserAlias = apps.get_model("registrations", "EndUserAlias")
    consolidate_exact_duplicates(apps)
    for name, acronym, street, city, province in END_USERS:
        full_address = ", ".join((street, city, province))
        normalized_name = normalize(name)
        defaults = {
            "official_name": name,
            "acronym": acronym,
            "government_branch": "Local government"
            if name.startswith(("City", "Province"))
            else "Executive",
            "organization_type": "Procuring entity",
            "sector": "Government",
            "province": province,
            "city_municipality": city,
            "street_address": street,
            "philgeps_reference": SOURCE_REFERENCE,
            "source_url": SOURCE_URL,
            "status": "verified",
            "is_active": True,
            "normalized_address": normalize(full_address),
        }
        end_user, _ = EndUser.objects.update_or_create(
            normalized_name=normalized_name,
            defaults=defaults,
        )
        for alias in ALIASES.get(name, []):
            EndUserAlias.objects.get_or_create(end_user=end_user, name=alias)


